import React, { useState, useEffect } from 'react';

const eventExplanations = {
  "order_created": "Order created from strategy decision",
  "partial_fill": "Order partially filled due to limited liquidity",
  "order_filled": "Order fully executed",
  // Add more mappings as needed based on your backend's event types
};

const StrategyInspector = ({ strategyId: propStrategyId, seed: propSeed, onReset }) => {
  const [strategyId, setStrategyId] = useState(propStrategyId || '');
  const [seed, setSeed] = useState(propSeed || 42);
  const [inspectionResult, setInspectionResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Update local state when props change
  useEffect(() => {
    if (propStrategyId) setStrategyId(propStrategyId);
    if (propSeed) setSeed(propSeed);
  }, [propStrategyId, propSeed]);

  // Fetch data when strategyId or seed changes from props or manual input
  useEffect(() => {
    if (strategyId && seed !== null) {
      handleInspectStrategy();
    } else {
      // Reset results if essential inputs are cleared
      setInspectionResult(null);
      setError(null);
    }
  }, [strategyId, seed]); // Depend on local state, which is updated by props or user input

  const handleInspectStrategy = async () => {
    setLoading(true);
    setError(null);
    setInspectionResult(null);

    try {
      const response = await fetch('http://localhost:8000/inspect_strategy', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          strategy_id: strategyId,
          seed: Number(seed),
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to inspect strategy');
      }

      const data = await response.json();
      setInspectionResult(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Calculate outcome layer details
  const totalExecutionSteps = inspectionResult?.execution_trace?.length || 0;
  const partialFillsCount = inspectionResult?.execution_trace?.filter(
    (trace) => trace.event === 'partial_fill'
  ).length || 0;

  return (
    <div className="p-4">
      <h2 className="text-2xl font-semibold mb-4">Strategy Inspector</h2>

      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="strategy_id">
          Strategy ID:
        </label>
        <input
          type="text"
          id="strategy_id"
          className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          value={strategyId}
          onChange={(e) => setStrategyId(e.target.value)}
          onBlur={handleInspectStrategy} // Trigger fetch on blur for manual changes
        />
      </div>

      <div className="mb-6">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="seed_inspect">
          Seed:
        </label>
        <input
          type="number"
          id="seed_inspect"
          className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          value={seed}
          onChange={(e) => setSeed(e.target.value)}
          onBlur={handleInspectStrategy} // Trigger fetch on blur for manual changes
        />
      </div>

      <button
        className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline mb-4"
        onClick={handleInspectStrategy}
        disabled={loading}
      >
        {loading ? 'Inspecting...' : 'Inspect Strategy'}
      </button>

      {error && <p className="text-red-500 mt-4">Error: {error}</p>}

      {inspectionResult && (
        <div className="mt-6 space-y-6">
          {/* Section 1: Decision Context */}
          <div className="border p-4 rounded-lg shadow-sm">
            <h3 className="text-xl font-semibold mb-2">Decision Context</h3>
            <p><span className="font-medium">Strategy ID:</span> {inspectionResult.strategy_id}</p>
            <p><span className="font-medium">Seed:</span> {seed}</p>
            <div className="mt-2">
              <p className="font-medium">Metrics:</p>
              <pre className="bg-gray-50 p-2 rounded-md text-sm text-gray-800">{JSON.stringify(inspectionResult.metrics, null, 2)}</pre>
            </div>
          </div>

          {/* Section 2: Execution Layer */}
          <div className="border p-4 rounded-lg shadow-sm">
            <h3 className="text-xl font-semibold mb-2">Execution Layer</h3>
            <div className="bg-gray-50 p-4 rounded-md max-h-60 overflow-y-auto">
              {inspectionResult.execution_trace.length > 0 ? (
                <ul className="list-disc list-inside text-sm text-gray-800">
                  {inspectionResult.execution_trace.map((trace, index) => (
                    <li key={index}>
                      <span className="font-medium">Step {trace.step}:</span> {trace.event} - {eventExplanations[trace.event] || 'No explanation available'}
                    </li>
                  ))}
                </ul>
              ) : (
                <p>No execution trace available.</p>
              )}
            </div>
          </div>

          {/* Section 3: Outcome Layer */}
          <div className="border p-4 rounded-lg shadow-sm">
            <h3 className="text-xl font-semibold mb-2">Outcome Layer</h3>
            <p><span className="font-medium">Final Metrics:</span></p>
            <pre className="bg-gray-50 p-2 rounded-md text-sm text-gray-800">{JSON.stringify(inspectionResult.metrics, null, 2)}</pre>
            <p className="mt-2"><span className="font-medium">Total Execution Steps:</span> {totalExecutionSteps}</p>
            <p><span className="font-medium">Count of Partial Fills:</span> {partialFillsCount}</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default StrategyInspector;
